    "mr": "📍 कोणतेही डीफॉल्ट स्थान सेट केलेले नाही. नकाशावर क्लिक करा आणि वर्तमान सेट करा.",
    "bn": "📍 কোনো ডিফল্ট অবস্থান সেট করা নেই। মানচিত্রে ক্লিক করুন এবং বর্তমান অবস্থান সেট করুন।",
    "gu": "📍 કોઈ ડિફૉલ્ટ સ્થાન સેટ કરેલ નથી. નકશા પર ક્લિક કરો અને વર્તમાન સેટ કરો.",
    "ml": "📍 സ്ഥിരസ്ഥിതി ലൊക്കേഷൻ സജ്ജമാക്കിയിട്ടില്ല. മാപ്പിൽ ക്ലിക്കുചെയ്‌ത് നിലവിലുള്ളത് സജ്ജമാക്കുക.",
    "pa": "📍 ਕੋਈ ਡਿਫੌਲਟ ਟਿਕਾਣਾ ਸੈੱਟ ਨਹੀਂ ਹੈ। ਨਕਸ਼ੇ 'ਤੇ ਕਲਿੱਕ ਕਰੋ ਅਤੇ ਮੌਜੂਦਾ ਸੈੱਟ ਕਰੋ।",
    "or": "📍 କୌଣସି ଡିଫଲ୍ଟ ସ୍ଥାନ ସେଟ୍ ହୋଇନାହିଁ। ମାନଚିତ୍ରରେ କ୍ଲିକ୍ କରନ୍ତୁ ଏବଂ ବର୍ତ୍ତମାନ ସେଟ୍ କରନ୍ତୁ।",
