    "ne": "📍 कुनै पूर्वनिर्धारित स्थान सेट गरिएको छैन। नक्सामा क्लिक गर्नुहोस् र हालको सेट गर्नुहोस्।",
    "si": "📍 පෙරනිමි ස්ථානයක් සකසා නැත. සිතියම ක්ලික් කර වත්මන් ස්ථානය සකසන්න."
