  "Year-long cropping; long ratoon cycles allow recovery if the first year runs dry.": {
    "kn": "ವರ್ಷವಿಡೀ ಬೆಳೆ; ಮೊದಲ ವರ್ಷ ಒಣಗಿದರೆ ದೀರ್ಘ ಕೂಳೆ ಚಕ್ರಗಳು ಚೇತರಿಕೆಗೆ ಅವಕಾಶ ನೀಡುತ್ತವೆ.",
    "hi": "साल भर की फसल; पहला साल सूखा रहने पर लंबे पेड़ी चक्र से सुधार संभव है।",
    "ta": "ஆண்டு முழுவதும் பயிரிடுதல்; முதல் ஆண்டு வறண்டால் நீண்ட மறுதாம்பு சுழற்சிகள் மீட்க உதவுகின்றன.",
    "te": "ఏడాది పొడవునా పంట; మొదటి సంవత్సరం ఎండిపోతే దీర్ఘ రేటూన్ చక్రాలు రికవరీకి వీలు కల్పిస్తాయి.",
    "mr": "वर्षभराचे पीक; पहिले वर्ष कोरडे गेल्यास लांब खोडवा चक्र सुधारणेस मदत करते.",
    "bn": "বছরব্যাপী ফসল; প্রথম বছর খরা হলে দীর্ঘ রেটুন চক্র পুনরুদ্ধারের সুযোগ দেয়।",
    "gu": "આખું વર્ષ પાક; જો પ્રથમ વર્ષ શુષ્ક રહે તો લાંબા રેટૂન ચક્ર પુનઃપ્રાપ્તિની મંજૂરી આપે છે.",
    "ml": "വർഷം മുഴുവൻ വിളവ്; ആദ്യ വർഷം വറ്റിയാൽ വീണ്ടെടുക്കാൻ നീണ്ട റാറ്റൂൺ ചക്രങ്ങൾ അനുവദിക്കുന്നു.",
    "pa": "ਸਾਲ ਭਰ ਦੀ ਫ਼ਸਲ; ਜੇਕਰ ਪਹਿਲਾ ਸਾਲ ਸੁੱਕਾ ਰਹੇ ਤਾਂ ਲੰਬੇ ਮੂਢੀ ਚੱਕਰ ਰਿਕਵਰੀ ਦੀ ਆਗਿਆ ਦਿੰਦੇ ਹਨ।",
    "or": "ବର୍ଷ ତମାମ ଫସଲ; ପ୍ରଥମ ବର୍ଷ ଶୁଖିଲା ରହିଲେ ଲମ୍ବା ଖୁଣ୍ଟି ଚକ୍ର ସୁଧାରିବାକୁ ସୁଯୋଗ ଦିଏ।",
    "sa": "वर्षपर्यन्तं सस्यम्; यदि प्रथमवर्षं शुष्कं भवति तर्हि दीर्घावशिष्टचक्राणि पुनरुद्धारम् अनुमन्यन्ते।",
    "as": "বছৰজোৰা শস্য; প্ৰথম বছৰটো শুকান হ’লে দীঘলীয়া ৰেটুন চক্ৰই উদ্ধাৰৰ সুযোগ দিয়ে।",
    "ur": "سال بھر کی فصل؛ اگر پہلا سال خشک رہے تو لمبے موڈھی کے چکر بحالی کی اجازت دیتے ہیں۔",
    "es": "Cultivo durante todo el año; ciclos largos de retoños permiten la recuperación si el primer año es seco.",
    "fr": "Culture sur toute l'année; les longs cycles de repousse permettent de récupérer si la première année est sèche.",
    "de": "Ganzjähriger Anbau; lange Ratoon-Zyklen ermöglichen Erholung, falls das erste Jahr trocken verläuft.",
    "it": "Coltivazione annuale; i lunghi cicli di ratoon consentono il recupero se il primo anno è secco.",
    "pt": "Cultivo durante todo o ano; ciclos longos de soca permitem recuperação se o primeiro ano for seco.",
    "ru": "Круглогодичный урожай; длинные циклы отавы позволяют восстановиться, если первый год выдастся засушливым.",
    "ja": "周年栽培。初年度が干ばつでも、長期の宿根（ラトゥーン）栽培により回復が可能です。",
    "ko": "연중 재배 작물; 첫해에 가뭄이 들더라도 긴 그루터기(ratoon) 주기로 회복이 가능합니다.",
    "zh-CN": "全年均可种植；若初年干旱，较长的宿根生长周期有助于恢复产量。",
    "zh-TW": "全年均可種植；若初年乾旱，較長的宿根生長週期有助於恢復產量。",
    "ar": "محصول على مدار العام؛ دورات الخلفة الطويلة تسمح بالتعافي إذا جف العام الأول.",
    "id": "Tanaman sepanjang tahun; siklus ratoon yang panjang memungkinkan pemulihan jika tahun pertama kering.",
    "tr": "Yıl boyu ekim; ilk yıl kurak geçerse uzun ratoon döngüleri toparlanmaya izin verir.",
    "vi": "Cây trồng quanh năm; các chu kỳ lưu gốc dài giúp phục hồi nếu năm đầu tiên bị khô hạn.",
    "th": "พืชที่ปลูกได้ตลอดทั้งปี วงจรตอซังที่ยาวนานช่วยให้ฟื้นตัวได้หากปีแรกแห้งแล้ง",
    "nl": "Jaarrond gewas; lange stoppelcycli zorgen voor herstel als het eerste jaar droog uitvalt.",
    "pl": "Uprawa całoroczna; długie cykle odrostów pozwalają na regenerację, jeśli pierwszy rok będzie suchy.",
    "uk": "Цілорічна культура; тривалі цикли відростання дозволяють відновитися, якщо перший рік посушливий.",
    "el": "Ολοετής καλλιέργεια. Οι μακροί κύκλοι πρέμνων επιτρέπουν ανάκαμψη εάν η πρώτη χρονιά είναι ξηρή.",
    "he": "גידול לאורך כל השנה; מחזורי רטון ארוכים מאפשרים התאוששות אם השנה הראשונה יבשה.",
    "sv": "Året-runt-gröda; långa ratoon-cykler tillåter återhämtning om det första året är torrt.",
    "sw": "Zao la mwaka mzima; mizunguko mirefu ya ratoon inaruhusu ufufuaji ikiwa mwaka wa kwanza utakuwa mkavu.",
    "tl": "Buong taong pananim; ang mahabang mga siklo ng ratoon ay nagbibigay-daan sa pagbawi kung matuyo ang unang taon.",
    "ms": "Tanaman sepanjang tahun; kitaran ratoon yang panjang membolehkan pemulihan jika tahun pertama kering.",
    "fa": "کشت در طول سال؛ چرخه‌های طولانی پاجوش در صورت خشک بودن سال اول، امکان بازیابی را فراهم می‌کنند.",
    "ne": "वर्षैभरिको बाली; पहिलो वर्ष खडेरी भएमा लामो खुट्टी चक्रले सुधारको अवसर दिन्छ।",
    "si": "වසර පුරා වගාව; පළමු වසර වියළි වුවහොත් දිගු රැටූන් චක්‍ර මඟින් යථා තත්ත්වයට පත්වීමට ඉඩ සලසයි."
  },
